// reproduce.js
// Run this with `node reproduce.js` after installing lighthouse (`npm install lighthouse`).

const Aggregate = require('lighthouse/lighthouse-core/aggregator/aggregate');

// 1) Define two audit results: one passing, one failing
const results = [
  {
    name: 'aria-attributes-valid',
    rawValue: true,
    score: true,
    displayValue: 'OK',
    contributesToScore: true,
  },
  {
    name: 'color-contrast',
    rawValue: false,
    score: false,
    displayValue: '8 elements fail this test',
    contributesToScore: true,
  }
];

// 2) Define a single aggregation with both audits, equal weight
const aggregation = {
  name: 'Accessibility',
  description: 'Accessibility checks',
  scored: true,
  categorizable: true,
  items: [{
    audits: {
      'aria-attributes-valid': { expectedValue: true, weight: 1 },
      'color-contrast':          { expectedValue: true, weight: 1 }
    }
  }]
};

// 3) Perform the aggregation
const output = Aggregate.aggregate(aggregation, results);

// 4) Inspect the computed overall score
console.log('Computed overall:', output.score[0].overall);

// Expected correct weighted average: (1*1 + 0*1) / 2 = 0.5
// Observed (buggy) output: 1.0
